#!/bin/bash
P="$(cd "$(dirname "$0")/.." && pwd)"; cd $P/assets/raw
until grep -q LAYERSDONE gen.log; do sleep 20; done
[ -s props.png ] || codex exec --skip-git-repo-check -s workspace-write -C $P/assets/raw "Use your image generation tool to create ONE NEW image (never reuse an existing file) and save it as $P/assets/raw/props.png. 1536x1024 PROP SPRITE SHEET, TRANSPARENT background, pixel-art HD-2D style matching the attached style reference, same top-down 3/4 RPG overworld camera. Follow the attached template: 6 columns x 4 rows of 256x256 cells; each cell holds ONE standalone object named in the template cell (street lamp, signpost, wooden fence segment, barrel stack, crate stack, market stall, hay cart, stone well, big rock, small rocks, bush, flowering bush, pine tree, oak tree, dead tree, tree stump, camping tent, campfire, small windmill, small farm field patch, ruined stone pillar, banner pole with blue flag, rowboat, glowing lava rock). Object base sits on the red baseline, centered, only a thin footprint shadow, no ground tile. No text, no grid lines, no characters." -i props-template.png -i world-bg.png < /dev/null > props.png.log 2>&1
echo "props.png rc=$?" >> gen.log; echo PROPSDONE >> gen.log
